35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$",
49	            message = "Phone number must be E.164: a '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    private String email;
54	
55	    @Column(name = "postcode")
56	    private String postcode;
57	
58	    @Column(name = "registration_date")
59	    private LocalDate registrationDate;
60	
61	    @Column(name = "birth_date")
62	    private LocalDate birthDate;
63	
64	    @Column(name = "customer_code")
65	    private String customerCode;
66	
67	    @Column(name = "household_id")
68	    private String householdId;
69	
70	    @Column(name = "namesake_count")
71	    private Integer namesakeCount;
72	
73	    @Column(name = "household_size")
74	    private Integer householdSize;
75	
76	    @Column(name = "bulk_signup_warning")
77	    private Boolean bulkSignupWarning;
78	
79	    @Column(name = "possible_duplicate")
80	    private Boolean possibleDuplicate;
81	
82	    @Column(name = "possible_duplicate_of")
83	    private Integer possibleDuplicateOf;
