90	    }
91	
92	    public void setAddress(String address) {
93	        this.address = address;
94	    }
95	
96	    public String getCity() {
97	        return this.city;
98	    }
99	
100	    public void setCity(String city) {
101	        this.city = city;
102	    }
103	
104	    public String getTelephone() {
105	        return this.telephone;
106	    }
107	
108	    public void setTelephone(String telephone) {
109	        this.telephone = telephone;
110	    }
111	
112	    public String getEmail() {
113	        return this.email;
114	    }
115	
116	    public void setEmail(String email) {
117	        this.email = email;
118	    }
119	
120	    public String getPostcode() {
121	        return this.postcode;
122	    }
123	
124	    public void setPostcode(String postcode) {
125	        this.postcode = postcode;
126	    }
127	
128	    public LocalDate getRegistrationDate() {
129	        return this.registrationDate;
130	    }
131	
132	    public void setRegistrationDate(LocalDate registrationDate) {
133	        this.registrationDate = registrationDate;
134	    }
135	
136	    public LocalDate getBirthDate() {
137	        return this.birthDate;
138	    }
139	
140	    public void setBirthDate(LocalDate birthDate) {
141	        this.birthDate = birthDate;
142	    }
143	
144	    public String getCustomerCode() {
145	        return this.customerCode;
146	    }
147	
148	    public void setCustomerCode(String customerCode) {
149	        this.customerCode = customerCode;
150	    }
151	
152	    public String getHouseholdId() {
153	        return this.householdId;
154	    }
155	
156	    public void setHouseholdId(String householdId) {
157	        this.householdId = householdId;
158	    }
159	
160	    public Integer getNamesakeCount() {
161	        return this.namesakeCount;
162	    }
163	
164	    public void setNamesakeCount(Integer namesakeCount) {
165	        this.namesakeCount = namesakeCount;
166	    }
167	
168	    public Integer getHouseholdSize() {
169	        return this.householdSize;
170	    }
171	
172	    public void setHouseholdSize(Integer householdSize) {
173	        this.householdSize = householdSize;
174	    }
175	
176	    public Boolean getBulkSignupWarning() {
177	        return this.bulkSignupWarning;
178	    }
179	
180	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
181	        this.bulkSignupWarning = bulkSignupWarning;
182	    }
183	
184	    public Boolean getPossibleDuplicate() {
185	        return this.possibleDuplicate;
186	    }
187	
188	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
189	        this.possibleDuplicate = possibleDuplicate;
190	    }
191	
192	    public Integer getPossibleDuplicateOf() {
193	        return this.possibleDuplicateOf;
194	    }
195	
196	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
197	        this.possibleDuplicateOf = possibleDuplicateOf;
198	    }
199	
200	    protected Set<Pet> getPetsInternal() {
201	        if (this.pets == null) {
202	            this.pets = new HashSet<>();
203	        }
204	        return this.pets;
205	    }
206	
207	    protected void setPetsInternal(Set<Pet> pets) {
208	        this.pets = pets;
209	    }
210	
211	    public List<Pet> getPets() {
212	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
213	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
214	        return Collections.unmodifiableList(sortedPets);
215	    }
216	
217	    public void setPets(List<Pet> pets) {
218	        this.pets = new HashSet<>(pets);
219	    }
220	
221	    public void addPet(Pet pet) {
222	        getPetsInternal().add(pet);
223	        pet.setOwner(this);
224	    }
225	
226	    /**
227	     * Return the Pet with the given name, or null if none found for this Owner.
228	     *
229	     * @param name to test
230	     * @return true if pet name is already in use
231	     */
232	    public Pet getPet(String name) {
233	        return getPet(name, false);
234	    }
235	
236	    /**
237	     * Return the Pet with the given name, or null if none found for this Owner.
238	     *
239	     * @param name to test
240	     * @return true if pet name is already in use
241	     */
242	    public Pet getPet(String name, boolean ignoreNew) {
243	        name = name.toLowerCase();
244	        for (Pet pet : getPetsInternal()) {
245	            if (!ignoreNew || !pet.isNew()) {
246	                String compName = pet.getName();
247	                compName = compName.toLowerCase();
248	                if (compName.equals(name)) {
249	                    return pet;
250	                }
251	            }
252	        }
253	        return null;
254	    }
255	
256	    public Pet getPet(Integer petId) {
257	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
258	    }
259	
260	    @Override
261	    public String toString() {
262	        return new ToStringCreator(this)
263	
264	            .append("id", this.getId())
265	            .append("new", this.isNew())
266	            .append("lastName", this.getLastName())
267	            .append("firstName", this.getFirstName())
268	            .append("address", this.address)
269	            .append("city", this.city)
270	            .append("telephone", this.telephone)
271	            .append("email", this.email)
272	            .toString();
273	    }
274	}
