15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "telephoneDisplay", expression = "java(org.springframework.samples.petclinic.model.TelephoneDisplay.of(owner))")
22	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
24	    @Mapping(target = "checkDigit", expression = "java(org.springframework.samples.petclinic.model.CheckDigit.of(owner))")
25	    @Mapping(target = "membershipNumber", expression = "java(owner.getCustomerCode() == null || owner.getRegistrationDate() == null ? null : owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
26	    @Mapping(target = "membershipPoints", expression = "java(org.springframework.samples.petclinic.model.MembershipPoints.of(owner))")
27	    @Mapping(target = "membershipLevel", expression = "java(org.springframework.samples.petclinic.model.MembershipLevel.of(owner))")
28	    @Mapping(target = "locality", expression = "java(org.springframework.samples.petclinic.model.Locality.of(owner))")
29	    @Mapping(target = "timezone", expression = "java(org.springframework.samples.petclinic.model.Timezone.of(owner))")
30	    @Mapping(target = "contactPreference", expression = "java(org.springframework.samples.petclinic.model.ContactPreference.of(owner))")
31	    @Mapping(target = "ageBand", expression = "java(org.springframework.samples.petclinic.model.AgeBand.of(owner))")
32	    @Mapping(target = "identityKey", expression = "java(org.springframework.samples.petclinic.model.IdentityKey.of(owner))")
33	    OwnerDto toOwnerDto(Owner owner);
34	
35	    Owner toOwner(OwnerDto ownerDto);
36	
37	    @Mapping(target = "id", ignore = true)
38	    @Mapping(target = "pets", ignore = true)
39	    Owner toOwner(OwnerFieldsDto ownerDto);
40	
41	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
42	
43	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
44	
45	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
46	        OwnerPageDto ownerPageDto = new OwnerPageDto();
47	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
48	        ownerPageDto.setPage(ownerPage.getNumber());
49	        ownerPageDto.setSize(ownerPage.getSize());
50	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
51	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
52	        return ownerPageDto;
53	    }
54	}
