1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	import java.util.Set;
7	import java.util.regex.Pattern;
8	
9	import net.officefloor.plugin.variable.Out;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.escalation.OwnerFieldsInvalidException;
12	import org.springframework.web.bind.annotation.RequestBody;
13	
14	/**
15	 * Rejects a create request that is missing or blank in any required owner field, before
16	 * {@link BuildOwner} runs. Reads the body once and republishes it for later steps.
17	 */
18	public class ValidateOwnerFields {
19	
20	    /** A syntactically valid address: local-part@domain with a dotted domain, no spaces. */
21	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
22	
23	    /** Disposable email domains rejected outright: an email in one of these is a 400. */
24	    private static final Set<String> DISPOSABLE_DOMAINS =
25	            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
26	
27	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
28	            throws OwnerFieldsInvalidException {
29	        List<String> errors = new ArrayList<>();
30	        checkRequired("firstName", request.getFirstName(), errors);
31	        checkRequired("lastName", request.getLastName(), errors);
32	        checkRequired("city", request.getCity(), errors);
33	        checkRequired("telephone", request.getTelephone(), errors);
34	        normalizeAddress(request, errors);
35	        normalizeTelephone(request, errors);
36	        normalizeEmail(request, errors);
37	        validatePostcode(request, errors);
38	        validateRegistrationDate(request, errors);
39	        if (!errors.isEmpty()) {
40	            throw new OwnerFieldsInvalidException(errors);
41	        }
42	        validated.set(request);
43	    }
44	
45	    private static void checkRequired(String field, String value, List<String> errors) {
46	        if (value == null || value.isBlank()) {
47	            errors.add(field);
48	        }
49	    }
50	
51	    /**
52	     * Normalizes the address (see {@link AddressNormalizer}) and stores the result back on
53	     * the request so later steps persist, compare and return the canonical form. The
54	     * address is required: a value that is blank after normalization is a 400 (adds an
55	     * "address" error) and is not stored back.
56	     */
57	    private static void normalizeAddress(OwnerFieldsDto request, List<String> errors) {
58	        String normalized = AddressNormalizer.normalize(request.getAddress());
59	        if (normalized.isEmpty()) {
60	            errors.add("address");
61	        }
62	        else {
63	            request.setAddress(normalized);
64	        }
65	    }
66	
67	    /**
68	     * Normalizes the telephone to E.164 form (see {@link TelephoneE164}), storing the
69	     * result back on the request so later steps persist and return it. A value that
70	     * cannot form a valid E.164 number is a 400 (adds a "telephone" error).
71	     */
72	    private static void normalizeTelephone(OwnerFieldsDto request, List<String> errors) {
73	        String telephone = request.getTelephone();
74	        if (telephone == null) {
75	            return;
76	        }
77	        String e164 = TelephoneE164.toE164(telephone);
78	        if (e164 != null) {
79	            request.setTelephone(e164);
80	        }
81	        else if (!errors.contains("telephone")) {
82	            errors.add("telephone");
83	        }
84	    }
85	
86	    /**
87	     * Email is optional. When present (non-blank) it must be a syntactically valid address
88	     * whose domain is not on the disposable-domain blocklist; an invalid or disposable value
89	     * is a 400 (adds an "email" error). A valid value is stored lower-cased back on the request
90	     * so later steps persist and return it lower-cased.
91	     */
92	    private static void normalizeEmail(OwnerFieldsDto request, List<String> errors) {
93	        String email = request.getEmail();
94	        if (email == null || email.isBlank()) {
95	            return;
96	        }
97	        String trimmed = email.trim();
98	        if (EMAIL.matcher(trimmed).matches() && !isDisposableDomain(trimmed)) {
99	            request.setEmail(trimmed.toLowerCase());
100	        }
101	        else if (!errors.contains("email")) {
102	            errors.add("email");
103	        }
104	    }
105	
106	    /** True when the email's domain (case-insensitive) is on the disposable-domain blocklist. */
107	    private static boolean isDisposableDomain(String email) {
108	        int at = email.lastIndexOf('@');
109	        if (at < 0) {
110	            return false;
111	        }
112	        return DISPOSABLE_DOMAINS.contains(email.substring(at + 1).toLowerCase());
113	    }
114	
115	    /**
116	     * Postcode is optional. When present (non-blank) it must be a 4-digit value that is valid
117	     * for the owner's city per the fixed region ranges (see
118	     * {@link org.springframework.samples.petclinic.model.Postcode}); an out-of-range or
