29	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
30	            owner.setPossibleDuplicate(false);
31	            owner.setPossibleDuplicateOf(null);
32	            return; // a declared household member is not a suspected duplicate
33	        }
34	        String lastName = owner.getLastName();
35	        String postcode = owner.getPostcode();
36	        String telephone = owner.getTelephone();
37	
38	        Owner match = null;
39	        if (postcode != null) {
40	            for (Owner existing : ownerRepository.findAll()) {
41	                if (postcode.equals(existing.getPostcode())
42	                        && equalsIgnoreCase(lastName, existing.getLastName())
43	                        && !equals(telephone, existing.getTelephone())) {
44	                    if (match == null || existing.getId() < match.getId()) {
45	                        match = existing;
46	                    }
47	                }
48	            }
49	        }
50	
51	        if (match != null) {
52	            owner.setPossibleDuplicate(true);
53	            owner.setPossibleDuplicateOf(match.getId());
54	        }
55	        else {
56	            owner.setPossibleDuplicate(false);
57	            owner.setPossibleDuplicateOf(null);
58	        }
59	    }
60	
61	    private static boolean equalsIgnoreCase(String a, String b) {
62	        return a == null ? b == null : a.equalsIgnoreCase(b);
63	    }
64	
